		'language': 'fq',
		'value': '1',
		'synonyms': 'critiques,critique,p1,p1s,p1\'s'
	},
	{
		'name': 'task',
		'element': 'priority',
		'language': 'fq',
		'value': '2',
		'synonyms': 'p2,p2s,p2\'s,hautement,élevée,à fort,important,haute'
	},
	{
		'name': 'task',
		'element': 'priority',
		'language': 'fq',
		'value': '3',
		'synonyms': 'p3,p3s,p3\'s'
	},
	{
		'name': 'task',
		'element': 'priority',
		'language': 'fq',
		'value': '4',
		'synonyms': 'p4,p4s,p4\'s'
	},
	{
